function esc(v){return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;').replace(/{/g,'&#123;').replace(/}/g,'&#125;').replace(/@@TISYA_/g,'&#64;@TISYA_');}
